import logging
import re
from collections import defaultdict
from pathlib import Path
from typing import Any, Iterator, Literal

import yaml
from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    PositiveInt,
    RootModel,
    field_validator,
    model_validator,
)

logger = logging.getLogger(__name__)

REPO_ROOT = Path(__file__).parent.parent.parent.parent
DATABASE_LIST_PATH = Path(__file__).parent / "lookup.yaml"
CURATED_LIST_PATH = Path(__file__).parent.parent / "curated" / "lookup.yaml"

LOW_LATENCY_CONCURRENCY_THRESHOLD = 8
HIGH_THROUGHPUT_CONCURRENCY_THRESHOLD = 32
KEY_PROFILES = {"Min Latency", "Balanced", "Max Throughput"}
PROFILE_DISPLAY_NAMES = {
    "latency": "Min Latency",
    "balanced": "Balanced",
    "throughput": "Max Throughput",
}
PROFILE_ORDER = {profile: idx for idx, profile in enumerate(PROFILE_DISPLAY_NAMES)}
VALIDATED_COMMIT_PATTERN = re.compile(r"^[0-9a-f]{40}$")
VALIDATED_VERSION_PATTERN = re.compile(r"^[0-9A-Za-z][0-9A-Za-z._+-]*$")
Profile = Literal["latency", "balanced", "throughput"]


class CuratedRecipe(BaseModel):
    """A curated (hand-tuned) recipe entry."""

    model_config = ConfigDict(extra="forbid")

    model: str = Field(description="HuggingFace model ID")
    arch: str = Field(description="Model architecture class name")
    config_path: str = Field(description="Relative path to YAML config")
    scenario: str = Field(default="", description="Deployment scenario label")
    gpu_compatibility: str = Field(default="Any", description="Compatible GPU families")
    disagg: bool = Field(default=False, description="Requires disaggregated serving")

    @field_validator("config_path")
    @classmethod
    def _validate_config_path(cls, v: str) -> str:
        p = Path(v)
        if p.is_absolute() or ".." in p.parts:
            raise ValueError(f"Invalid config path: {v}")
        return v


class CuratedRecipeList(RootModel[list[CuratedRecipe]]):
    """Validated list of curated recipe entries."""

    @classmethod
    def from_yaml(cls, yaml_path: Path) -> "CuratedRecipeList":
        """Load and validate curated recipe list from YAML file."""
        try:
            with open(yaml_path, encoding="utf-8") as f:
                data = yaml.safe_load(f)
            return cls(data)
        except Exception as e:
            logger.error("Failed to load curated recipe list from %s: %s", yaml_path, e)
            raise

    def __iter__(self) -> Iterator[CuratedRecipe]:
        return iter(self.root)

    def __len__(self) -> int:
        return len(self.root)


class Recipe(BaseModel):
    """Recipe record for scenario list."""

    model_config = ConfigDict(extra="forbid")

    model: str = Field(min_length=1, description="Model name")
    arch: str = Field(min_length=1, description="Model architecture class name")
    gpu: str = Field(min_length=1, description="GPU name")
    isl: PositiveInt = Field(description="Input sequence length")
    osl: PositiveInt = Field(description="Output sequence length")
    concurrency: PositiveInt = Field(description="Concurrency")
    config_path: str = Field(min_length=1, description="Configuration path")
    num_gpus: PositiveInt = Field(description="Number of GPUs")
    profile: Profile | None = Field(
        default=None,
        description="Profile discriminator used only when the workload key has multiple configs",
    )
    validated_trtllm_commit: str | None = Field(
        default=None,
        description="Full TensorRT-LLM commit SHA against which the recipe was validated",
    )
    validated_trtllm_version: str | None = Field(
        default=None,
        description="TensorRT-LLM release version reported by the validation source",
    )

    @field_validator("validated_trtllm_commit")
    @classmethod
    def _validate_commit(cls, value: str | None) -> str | None:
        if value is None:
            return None
        normalized = value.strip().lower()
        if not VALIDATED_COMMIT_PATTERN.fullmatch(normalized):
            raise ValueError("validated_trtllm_commit must be a full 40-character Git SHA")
        return normalized

    @field_validator("validated_trtllm_version")
    @classmethod
    def _validate_version(cls, value: str | None) -> str | None:
        if value is None:
            return None
        normalized = value.strip()
        if not VALIDATED_VERSION_PATTERN.fullmatch(normalized):
            raise ValueError("validated_trtllm_version must be a release-tag-safe version")
        return normalized

    @model_validator(mode="after")
    def _validate_provenance_pair(self) -> "Recipe":
        if bool(self.validated_trtllm_commit) != bool(self.validated_trtllm_version):
            raise ValueError(
                "validated_trtllm_commit and validated_trtllm_version must be provided together"
            )
        return self

    def load_config(self) -> dict[str, Any]:
        """Load and return the YAML config at config_path."""
        config_relative_path = Path(self.config_path)
        # Ensure config path is within the repo root
        if config_relative_path.is_absolute() or ".." in config_relative_path.parts:
            raise ValueError(f"Invalid config path: {self.config_path}")
        full_path = REPO_ROOT / self.config_path
        if not full_path.exists():
            raise FileNotFoundError(f"Config not found: {full_path}")
        with open(full_path, encoding="utf-8") as f:
            return yaml.safe_load(f)


class RecipeList(RootModel[list[Recipe]]):
    @model_validator(mode="after")
    def _validate_conflict_profiles(self) -> "RecipeList":
        groups = defaultdict(list)
        for recipe in self.root:
            key = (
                recipe.model,
                recipe.gpu,
                recipe.num_gpus,
                recipe.isl,
                recipe.osl,
                recipe.concurrency,
            )
            groups[key].append(recipe)

        required_profiles = {"latency", "throughput"}
        for key, recipes in groups.items():
            profiles = [recipe.profile for recipe in recipes]
            if len(recipes) == 1:
                if profiles[0] is not None:
                    raise ValueError(f"profile is only allowed for conflicting workload key {key}")
                continue
            profile_set = set(profiles)
            if (
                None in profile_set
                or len(profile_set) != len(profiles)
                or not required_profiles.issubset(profile_set)
            ):
                raise ValueError(
                    "conflicting workload key "
                    f"{key} must have exactly one latency and throughput profile, "
                    "with an optional balanced profile"
                )
        return self

    @classmethod
    def from_yaml(cls, yaml_path: Path) -> "RecipeList":
        """Load and validate recipe list from YAML file."""
        with open(yaml_path, encoding="utf-8") as f:
            data = yaml.safe_load(f)
        return cls(data)

    def __iter__(self) -> Iterator[Recipe]:
        return iter(self.root)

    def __len__(self) -> int:
        return len(self.root)


def assign_profile(num_recipes: int, idx: int, concurrency: int) -> str:
    """Assign performance profile to a recipe based on its position in a concurrency-sorted list."""
    if num_recipes == 1:
        if concurrency <= LOW_LATENCY_CONCURRENCY_THRESHOLD:
            return "Low Latency"
        elif concurrency >= HIGH_THROUGHPUT_CONCURRENCY_THRESHOLD:
            return "High Throughput"
        else:
            return "Balanced"
    elif idx == 0:
        return "Min Latency"
    elif idx == num_recipes - 1:
        return "Max Throughput"
    elif idx in ((num_recipes - 1) // 2, num_recipes // 2):
        return "Balanced"
    elif idx < num_recipes // 2:
        return "Low Latency"
    else:
        return "High Throughput"


def select_key_recipes(recipes: list[Recipe]) -> list[tuple[Recipe, str]]:
    """Select key recipes (min latency, balanced, max throughput) from a list of recipes."""
    if not recipes:
        return []

    sorted_recipes = sorted(
        recipes,
        key=lambda r: (r.concurrency, PROFILE_ORDER.get(r.profile, -1)),
    )
    n = len(sorted_recipes)

    result = []
    seen_profiles = set()
    for idx, recipe in enumerate(sorted_recipes):
        profile = assign_profile(n, idx, recipe.concurrency)
        # For n==1, keep whatever profile is assigned
        # For n>=2, only keep key profiles and dedupe (for even n, two indices get "Balanced")
        if n == 1 or (profile in KEY_PROFILES and profile not in seen_profiles):
            result.append((recipe, profile))
            seen_profiles.add(profile)
    return result

from __future__ import annotations

from pathlib import Path
from typing import Any, List, Optional, Union

from pydantic import (AliasChoices, BaseModel, Field, computed_field,
                      model_validator)

from tensorrt_llm.bench.dataclasses.statistics import PercentileStats
from tensorrt_llm.executor.request import LoRARequest


class BenchmarkEnvironment(BaseModel):
    model: str
    checkpoint_path: Optional[Path]
    workspace: Path
    revision: Optional[str] = None
    telemetry_config: Optional[Any] = None


class InferenceRequest(BaseModel):
    task_id: int
    prompt: Optional[Union[str, Any]] = None
    output_tokens: int
    input_ids: Optional[List[int]] = Field(
        alias=AliasChoices("input_ids", "logits"))
    lora_request: Optional[LoRARequest] = None
    turns: Optional[List[str]] = None
    category: Optional[str] = None
    question_id: Optional[int] = None

    @model_validator(mode="after")
    def verify_prompt_and_logits(self) -> InferenceRequest:
        if self.prompt is None and self.input_ids is None and self.turns is None:
            raise ValueError(
                f"prompt, input_ids, and turns for task {self.task_id} are all None."
            )
        return self

    @property
    def is_multi_turn(self) -> bool:
        return self.turns is not None and len(self.turns) > 1


class DatasetMetadata(BaseModel):
    isl_stats: PercentileStats
    osl_stats: PercentileStats
    seq_len_stats: PercentileStats
    num_requests: int
    dataset_path: Optional[Path] = None

    @computed_field
    @property
    def max_isl(self) -> int:
        return int(self.isl_stats.maximum)

    @computed_field
    @property
    def max_osl(self) -> int:
        return int(self.osl_stats.maximum)

    @computed_field
    @property
    def max_sequence_length(self) -> int:
        return int(self.seq_len_stats.maximum)

    @computed_field
    @property
    def avg_isl(self) -> int:
        return int(self.isl_stats.average)

    @computed_field
    @property
    def avg_osl(self) -> int:
        return int(self.osl_stats.average)

    @computed_field
    @property
    def avg_sequence_length(self) -> int:
        return int(self.seq_len_stats.average)

    def _format_number(self, value: float) -> str:
        """Format number to fit within 9 characters including decimal."""
        if value >= 100000:
            return f"{value:9.2e}".ljust(
                9
            )  # Scientific notation for large numbers, padded to 9 characters
        return f"{value:9.4f}".ljust(
            9)  # Fixed point for smaller numbers, padded to 9 characters

    def get_summary_for_print(self) -> str:
        form = self._format_number
        return (
            "\n===========================================================\n"
            "= DATASET DETAILS\n"
            "===========================================================\n"
            f"Dataset Path:         {self.dataset_path}\n"
            f"Number of Sequences:  {self.num_requests}\n"
            "\n-- Percentiles statistics ---------------------------------\n\n"
            "        Input              Output           Seq. Length\n"
            "-----------------------------------------------------------\n"
            f"MIN:  {form(self.isl_stats.minimum)}          {form(self.osl_stats.minimum)}          {form(self.seq_len_stats.minimum)}\n"
            f"MAX:  {form(self.isl_stats.maximum)}          {form(self.osl_stats.maximum)}          {form(self.seq_len_stats.maximum)}\n"
            f"AVG:  {form(self.isl_stats.average)}          {form(self.osl_stats.average)}          {form(self.seq_len_stats.average)}\n"
            f"P50:  {form(self.isl_stats.p50)}          {form(self.osl_stats.p50)}          {form(self.seq_len_stats.p50)}\n"
            f"P90:  {form(self.isl_stats.p90)}          {form(self.osl_stats.p90)}          {form(self.seq_len_stats.p90)}\n"
            f"P95:  {form(self.isl_stats.p95)}          {form(self.osl_stats.p95)}          {form(self.seq_len_stats.p95)}\n"
            f"P99:  {form(self.isl_stats.p99)}          {form(self.osl_stats.p99)}          {form(self.seq_len_stats.p99)}\n"
            "===========================================================\n")

def get_visual_gen_model_type(model_path: str):
    for partial_model_name, model_type in VISUAL_GEN_PARTIAL_MODEL_NAME_TO_MODEL_TYPE.items():
        if partial_model_name.lower() in model_path.lower():
            return model_type

    raise ValueError(
        f"Unknown VISUAL_GEN model type for model path: {model_path},"
        f"available models: {VISUAL_GEN_PARTIAL_MODEL_NAME_TO_MODEL_TYPE.keys()}"
    )


def collect_explicit_cli_keys(
    *,
    exclude: Iterable[str] = (),
    translate: Optional[Mapping[str, str]] = None,
) -> Set[str]:
    """Return CLI flag names the user typed on the command line.

    Reads the active Click context and selects parameters whose source is
    `ParameterSource.COMMANDLINE`. `exclude` removes meta flags that aren't
    config keys (e.g. `extra_llm_api_options`, `config`). `translate` maps
    each Click parameter name to the LlmArgs field name (or merge-function
    CLI scalar name) used by `update_llm_args_with_extra_options`; entries
    not present in the map pass through unchanged.
    """
    ctx = click.get_current_context()
    explicit = {
        name for name in ctx.params if ctx.get_parameter_source(name) == ParameterSource.COMMANDLINE
    } - set(exclude)
    if translate is None:
        return explicit
    return {translate.get(name, name) for name in explicit}


def get_visual_gen_num_gpus(diffusion_config: dict) -> int:
    """Compute the number of GPUs from a visual_gen config.

    Uses ParallelConfig.model_construct (skips env validators)
    so this is safe to call from non-worker processes.
    """
    parallel = diffusion_config.get("parallel_config", {})
    if isinstance(parallel, dict):
        parallel = ParallelConfig.model_construct(**parallel)
    return parallel.n_workers

def update_llm_args_with_extra_dict(
        llm_args: Dict,
        llm_args_dict: Dict,
        extra_llm_api_options: Optional[str] = None,
        explicit_cli_keys: Optional[Set[str]] = None) -> Dict:
    """Merge YAML overrides into a CLI-derived llm_args dict.

    If `explicit_cli_keys` is provided, those CLI flag names override any
    conflicting YAML values. CLI flags whose name does not match the
    LlmArgs field name (e.g. `--free_gpu_memory_fraction` constructs
    `kv_cache_config.free_gpu_memory_fraction`) are mapped to the nested
    field they target.

    If `explicit_cli_keys` is None, YAML wins on conflicts.
    """
    # CLI scalar -> nested KvCacheConfig field. Callers add the CLI scalar
    # name to `explicit_cli_keys` to make it win over YAML's same-named
    # field inside `kv_cache_config:`.
    cli_to_kv_cache_field = {
        "free_gpu_memory_fraction": "free_gpu_memory_fraction",
        "kv_cache_dtype": "dtype",
        "enable_block_reuse": "enable_block_reuse",
    }
    explicit_cli_keys = explicit_cli_keys or set()

    if 'hf_revision' in llm_args_dict:
        llm_args_dict.setdefault('revision', llm_args_dict.pop('hf_revision'))

    # Deep merge kv_cache_config to prevent partial YAML kv_cache_config from replacing the complete kv_cache_config
    if 'kv_cache_config' in llm_args and 'kv_cache_config' in llm_args_dict:
        base_kv_config = llm_args['kv_cache_config']
        if isinstance(base_kv_config, KvCacheConfig):
            base_kv_config = base_kv_config.model_dump(exclude_unset=True)
        merged = base_kv_config | llm_args_dict['kv_cache_config']
        for cli_name, kv_field in cli_to_kv_cache_field.items():
            if cli_name in explicit_cli_keys and kv_field in base_kv_config:
                merged[kv_field] = base_kv_config[kv_field]
        llm_args_dict['kv_cache_config'] = merged

    # Deep merge telemetry_config: YAML can override fields like `disabled`,
    # but `usage_context` is determined by the CLI entry point and must not
    # be overridden by user config. When `--telemetry/--no-telemetry` was
    # typed explicitly, CLI's `disabled` wins over YAML.
    if 'telemetry_config' in llm_args and 'telemetry_config' in llm_args_dict:
        yaml_tc = llm_args_dict['telemetry_config']
        if not isinstance(yaml_tc, (dict, TelemetryConfig)):
            # YAML value is null / false / etc. — drop it so the CLI default
            # is preserved by the field_mapping coercion step below.
            del llm_args_dict['telemetry_config']
        else:
            base_tc = llm_args['telemetry_config']
            if isinstance(base_tc, TelemetryConfig):
                base_tc = base_tc.model_dump(exclude_unset=True)
            if isinstance(yaml_tc, TelemetryConfig):
                yaml_tc = yaml_tc.model_dump(exclude_unset=True)
            yaml_tc.pop('usage_context', None)
            merged = base_tc | yaml_tc
            if "telemetry" in explicit_cli_keys and 'disabled' in base_tc:
                merged['disabled'] = base_tc['disabled']
            llm_args_dict['telemetry_config'] = merged

    if 'multimodal_config' in llm_args_dict:
        yaml_mm = llm_args_dict['multimodal_config']
        if yaml_mm is None:
            yaml_mm = {}
        if isinstance(yaml_mm, MultimodalConfig):
            yaml_mm = yaml_mm.model_dump(exclude_unset=True)
        if isinstance(yaml_mm, dict):
            base_mm = llm_args.get('multimodal_config', {})
            if isinstance(base_mm, MultimodalConfig):
                base_mm = base_mm.model_dump(exclude_unset=True)
            if not isinstance(base_mm, dict):
                base_mm = {}
            merged = dict(base_mm) | dict(yaml_mm)
            llm_args_dict['multimodal_config'] = merged

    # Drop YAML keys claimed by explicit CLI flags so the outer merge below
    # cannot overwrite them. Warn only when the CLI value actually differs from
    # the YAML value, so users who relied on the previous "YAML wins" behavior
    # are notified that CLI now takes precedence.
    if explicit_cli_keys:
        overridden = sorted(
            k for k in llm_args_dict
            if k in explicit_cli_keys and llm_args.get(k) != llm_args_dict[k])
        if overridden:
            logger.warning(
                f"Explicit CLI flag(s) {overridden} override the value(s) set "
                f"in the YAML config; CLI takes precedence.")
        llm_args_dict = {
            k: v
            for k, v in llm_args_dict.items() if k not in explicit_cli_keys
        }

    field_mapping = {
        "quant_config": QuantConfig,
        "calib_config": CalibConfig,
        "decoding_config": DecodingConfig,
        "lora_config": LoraConfig,
        "moe_config": MoeConfig,
        "nvfp4_gemm_config": Nvfp4GemmConfig,
        "attention_dp_config": AttentionDpConfig,
        "reorder_policy_config": ReorderRequestPolicyConfig,
        "kv_cache_config": KvCacheConfig,
        "dwdp_config": DwdpConfig,
        "multimodal_config": MultimodalConfig,
        "telemetry_config": TelemetryConfig,
    }
    for field_name, field_type in field_mapping.items():
        if field_name in llm_args_dict:
            llm_args_dict[field_name] = field_type(**llm_args_dict[field_name])
            if field_name in llm_args:
                extra_llm_str = f" because it's specified in {extra_llm_api_options}" if extra_llm_api_options else ""
                logger.info(f"YAML overrides {field_name}{extra_llm_str}")

    llm_args = llm_args | llm_args_dict

    return llm_args


def update_llm_args_with_extra_options(
